            return Mono.empty();
        }

        if (request.getServicePlanName() != null && !request.getServicePlanName().isEmpty()) {
            return Mono.empty();
        }

        return Flux.fromIterable(servicePlans)
            .filter(servicePlan -> ResourceUtils.getEntity(servicePlan).getPubliclyVisible())
