                + "class InnerScope {\n"
                + "    int x = 0;\n"
                + "    void method() {\n"
                + "        {\n"
                + "            var x = 1;\n"
                + "            System.out.println(x);   // prints 1\n"
                + "        }\n"
                + "        System.out.println(x);       // prints 0\n"
                + "    }\n"
