		assertEquals(m2, m.getTranspose());
		assertEquals(m2, m.getTransposeView());
		assertEquals(m2, m.toMatrixTranspose());

		m2=m2.getTranspose();
		assertEquals(m,m2);

		assertEquals(m.getTranspose().innerProduct(m),m.transposeInnerProduct(m));
