    result = prime * result + minutesBefore;
    result = prime * result + (int) (time ^ (time >>> 32));
    if (instanceFilterChain != null)
      result = prime * result + instanceFilterChain.hashCode();
    return result;
  }

  @Override
  public boolean equals(Object obj) {
