							} else {
								dropIngots(e.getLocation());
								TARGET_TO_ABILITY.get(targetEntity).remove();
							}
						} else {
							DamageHandler.damageEntity(e, player, damage, this);
							dropIngots(e.getLocation(), ii.getItemStack().getAmount());
							remove();
						}

						ii.remove();
						break;
					}
				}
			}
		}

