				do {
					try {
						mainThread.join();
						joined = true;
					} catch (InterruptedException ex) {
						interrupted = true;
					}
				} while (!joined);
				if (interrupted)
					Thread.currentThread().interrupt();
			}
		}, "Server stopping"));
	}

	private boolean readFavicon() throws IOException {
