				FAVICON = "data:image/png;base64," + DatatypeConverter.printBase64Binary(baos.toByteArray());
				return true;
			} else {
				EnderLogger.warn("Your server-icon.png needs to be 64*64!");
				return false;
			}
		}catch(Exception e){
			return false;
		}
	}

