			}
		}
		return null;
	}

	public Entity getEntityById(int targetId) {
		for (EnderWorld w : this.worlds) {
			for (Entity e : w.entities) {
				if (e.getEntityId() == targetId) {
					return e;
				}
			}
		}
		for (EnderPlayer ep : this.onlinePlayers) {
			if (ep.getEntityId() == targetId) {
				return ep;
			}
		}
		return null;
	}
